{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "자전거 등록 시 자전거 주차장에서 우선 주차 가능 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "자전거를 관할 자치구에 등록해 두면 자전거주차장의 설치·관리자는 등록된 자전거에 대하여 자전거주차장에 우선적으로 주차가 될 수 있도록 하여야 한다. 따라서 등록된 자전거는 자전거 주차장에서 우선 주차가 가능하다.",
          "b_ids": "자전거:제10조제1항"
        }
      ],
      "e_status": "ANSWERED"
    },
    {
      "a_request": "R2",
      "b_asked": "시에서 운영하는 자전거 수리센터에서 등록 시 혜택 여부",
      "c_basis": "APPLIED",
      "d_claims": [
        {
          "a_text": "자전거를 관할 자치구에 등록하여 이용 확인이 가능한 자전거이용자에 대해서는 시장이 직접 운영하거나 민간단체 등에 위탁한 자전거 수리센터 등 시설 이용 시 요금 할인 등 혜택을 부여할 수 있다. 따라서 시에서 운영하는 수리센터에서도 등록 시 요금 할인 등 혜택을 받을 수 있다.",
          "b_ids": "자전거:제15조제2항, 자전거:제2조제3호"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
